 "content": "from collections import Counter, deque


def transform(grid):
    """Fill each rectangular frame with a checkerboard using the correspondingly ranked loose color."""
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    seen = set()
    frames = []

    # Frames are monochrome, 4-connected rectangular outlines. Loose colored cells
    # are isolated and therefore do not pass this perimeter test.
    for r in range(h):
        for c in range(w):
            color = a[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and a[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            top = min(y for y, x in comp)
            bottom = max(y for y, x in comp)
            left = min(x for y, x in comp)
            right = max(x for y, x in comp)
            if bottom - top < 2 or right - left < 2:
                continue
            cells = set(comp)
            perimeter = {
                (y, x)
                for y in range(top, bottom + 1)
                for x in range(left, right + 1)
                if y in (top, bottom) or x in (left, right)
            }
            if cells == perimeter:
                frames.append((top, bottom, left, right, color))

    frame_colors = {f[4] for f in frames}
    counts = Counter(a[r][c] for r in range(h) for c in range(w)
                     if a[r][c] != 0 and a[r][c] not in frame_colors)
    loose_colors = sorted(counts, key=lambda col: (counts[col], col))
    frames.sort(key=lambda f: ((f[1]-f[0]-1) * (f[3]-f[2]-1), f[0], f[2]))

    # Retain only the frame outlines; all loose markers are used as color keys.
    result = [[0] * w for _ in range(h)]
    for top, bottom, left, right, color in frames:
        for x in range(left, right + 1):
            result[top][x] = result[bottom][x] = color
        for y in range(top, bottom + 1):
            result[y][left] = result[y][right] = color

    for frame, fill in zip(frames, loose_colors):
        top, bottom, left, right, _ = frame
        for y in range(top + 1, bottom):
            for x in range(left + 1, right):
                if (y - top - 1 + x - left - 1) % 2 == 0:
                    result[y][x] = fill
    return result
